import axios from 'axios';

const API_BASE_URL = 'https://192.168.0.28:8000';

const api = axios.create({
  baseURL: API_BASE_URL,
  withCredentials: true,
  timeout: 10000,
});

// Логи для разработки
api.interceptors.request.use(config => {
  console.log(`→ ${config.method?.toUpperCase()} ${config.url}`, config.data);
  return config;
});

api.interceptors.response.use(
  (response) => {
    console.log(`← ${response.status} ${response.config.url}`, response.data);
    return response;
  },
  (error) => {
    console.error('API Error:', error.response?.data || error.message);
    return Promise.reject(error);
  }
);

// === АУТЕНТИФИКАЦИЯ ===
export const authAPI = {
  login: (email, password) =>
    api.post('/auth/login', { email, password }),

  register: (userData) =>
    api.post('/auth/register', userData),

  logout: () =>
    api.post('/auth/logout'),

  getMe: () =>
    api.get('/auth/me'),
};

// === СЧЕТА И ПОРТФЕЛЬ ===
export const accountsAPI = {
  // Получение списка счетов
  getAccounts: () => api.get('/accounts/'),
  
  // Открытие счета в песочнице
  openAccount: (accountType = "ACCOUNT_TYPE_TINKOFF") => 
    api.post('/accounts/open', { account_type: accountType }),
  
  // Пополнение счета в песочнице
  payIn: (amount, currency = "RUB", accountId = null) => 
    api.post('/accounts/payin', { 
      amount, 
      currency, 
      account_id: accountId 
    }),
  
  // Получение баланса
  getBalance: (accountId = null) => 
    api.get('/accounts/balance', { 
      params: { account_id: accountId } 
    }),
  
  // Получение портфеля
  getPortfolio: (accountId = null) => 
    api.get('/accounts/portfolio', { 
      params: { account_id: accountId } 
    }),
  
  // Закрытие счета (песочница)
  closeAccount: (accountId) => 
    api.delete(`/accounts/${accountId}`),
};

// === ТОРГОВЛЯ ===
export const tradeAPI = {
  getPortfolio: (accountId = null) => 
    accountsAPI.getPortfolio(accountId),
  
  executeOrder: (orderData) => 
    api.post('/trade/execute', orderData),
};

// === АКЦИИ И ДАННЫЕ ===
export const stocksAPI = {
  // Получение списка акций
  getStocks: (skip = 0, limit = 100, sector = null) =>
    api.get('/stocks/', {
      params: { skip, limit, sector }
    }),
  
  // Получение акции с ценами
  getStockWithPrices: (symbol, days = 30) =>
    api.get(`/stocks/${symbol}`, {
      params: { days }
    }),
  
  // Получение исторических цен
  getStockPrices: (symbol, startDate = null, endDate = null) =>
    api.get(`/stocks/${symbol}/prices`, {
      params: { start_date: startDate, end_date: endDate }
    }),
  
  // Получение фич для ML
  getStockFeatures: (symbol, startDate, endDate) =>
    api.get(`/stocks/${symbol}/features`, {
      params: { start_date: startDate, end_date: endDate }
    }),
};

// === МОДЕЛИ ML ===
export const modelsAPI = {
  // Обучение SVR модели
  trainSVR: (params) => 
    api.post('/models/train/svr', params),
  
  // Получение моделей пользователя
  getUserModels: () => 
    api.get('/models/my-models'),
  
  // Получение сессий обучения
  getTrainingSessions: () => 
    api.get('/models/training-sessions'),
};

// === БЭКТЕСТ ===
export const backtestAPI = {
  // Запуск бэктеста
  runBacktest: (requestData) => 
    api.post('/backtest/run', requestData),
  
  // Получение результатов бэктеста
  getBacktestResults: (skip = 0, limit = 50) => 
    api.get('/backtest/results', {
      params: { skip, limit }
    }),
};

// === РЫНОК ===
export const marketAPI = {
  loadCandles: (figi, days = 1) =>
    api.get(`/market/candles/${figi}?days=${days}`),
  
  getCurrentPrice: (figi) =>
    api.get(`/market/current-price/${figi}`),
};

export default api;
